script:
(function () {
  'use strict';
  // One year's required minimum distribution for a surviving spouse who is the sole beneficiary
  // of a traditional IRA, under the option the spouse chooses. RMD = balance on Dec 31 of the prior
  // year / divisor.
  //   Year of death: if the owner died on or after the required beginning date (RBD), the owner's
  //     own RMD (Uniform Lifetime Table at the owner's age) is still due; otherwise nothing.
  //   Treat as your own: Uniform Lifetime Table at your age, from the year you reach your own RMD
  //     age (first one can wait until April 1 of the next year).
  //   Remain a beneficiary: Single Life Table at your age (looked up again each year); starts the
  //     year after death, or the year the owner would have reached RMD age if the owner died before
  //     the RBD. Died on/after the RBD: larger of that and the owner's remaining life expectancy.
  //   Spousal election (IRC 401(a)(9)(B)(iv), proposed Treas. Reg. 1.401(a)(9)-5(g)(3)(ii)): same
  //     timing, Uniform Lifetime Table at your age; only if the first RMD year is 2024 or later.
  //   10-year rule (owner died before the RBD only): nothing due until the whole balance by
  //     Dec 31 of the 10th year after death.
  // Checked in Node (scratch tests): owner born 1950-04-20, died 2024-09-15 (after RBD April 1,
  // 2023), spouse born 1953-07-10, 2026, $400,000: beneficiary max(Table I(73) 16.4, owner
  // Table I(74) 15.6 - 2 = 13.6) = 16.4 -> $24,390.24; own and election Uniform(73) 26.5 ->
  // $15,094.34, own deadline April 1, 2027; year of death 2024: Uniform(74) 25.5 -> $15,686.27.
  // Owner died before RBD (born 1960, died 2025): beneficiary RMD $0 until 2035; 10-year rule
  // whole balance in 2035.
  //
  // ---- IRS life expectancy tables (distribution years 2022 and later; used for 2026) -------
  // SINGLE_LIFE: IRS Pub. 590-B (2025), Appendix B, Table I (Treas. Reg. 1.401(a)(9)-9(b)), ages 0-120+.
  // UNIFORM: Treas. Reg. 1.401(a)(9)-9(c) Uniform Lifetime Table as republished for ages 10-120+
  //   in proposed regs REG-103529-23 (89 FR 58644, July 19, 2024); ages 72+ match Pub. 590-B Table III.
  // Every value was compared programmatically with the IRS text.
  var SINGLE_LIFE = [
    84.6, 83.7, 82.8, 81.8, 80.8, 79.8, 78.8, 77.9, 76.9, 75.9, 74.9, 73.9, 72.9, 71.9, 70.9,
    69.9, 69.0, 68.0, 67.0, 66.0, 65.0, 64.1, 63.1, 62.1, 61.1, 60.2, 59.2, 58.2, 57.3, 56.3,
    55.3, 54.4, 53.4, 52.5, 51.5, 50.5, 49.6, 48.6, 47.7, 46.7, 45.7, 44.8, 43.8, 42.9, 41.9,
    41.0, 40.0, 39.0, 38.1, 37.1, 36.2, 35.3, 34.3, 33.4, 32.5, 31.6, 30.6, 29.8, 28.9, 28.0,
    27.1, 26.2, 25.4, 24.5, 23.7, 22.9, 22.0, 21.2, 20.4, 19.6, 18.8, 18.0, 17.2, 16.4, 15.6,
    14.8, 14.1, 13.3, 12.6, 11.9, 11.2, 10.5, 9.9, 9.3, 8.7, 8.1, 7.6, 7.1, 6.6, 6.1,
    5.7, 5.3, 4.9, 4.6, 4.3, 4.0, 3.7, 3.4, 3.2, 3.0, 2.8, 2.6, 2.5, 2.3, 2.2,
    2.1, 2.1, 2.1, 2.0, 2.0, 2.0, 2.0, 2.0, 1.9, 1.9, 1.8, 1.8, 1.6, 1.4, 1.1,
    1.0
  ];
  var UNIFORM = [
    88.2, 87.2, 86.2, 85.2, 84.2, 83.2, 82.2, 81.2, 80.2, 79.2, 78.2, 77.2, 76.2, 75.2, 74.2,
    73.3, 72.3, 71.3, 70.3, 69.3, 68.3, 67.3, 66.3, 65.3, 64.3, 63.3, 62.3, 61.3, 60.3, 59.4,
    58.4, 57.4, 56.4, 55.4, 54.4, 53.4, 52.4, 51.5, 50.5, 49.5, 48.5, 47.5, 46.5, 45.6, 44.6,
    43.6, 42.6, 41.6, 40.7, 39.7, 38.7, 37.7, 36.8, 35.8, 34.9, 33.9, 33.0, 32.0, 31.1, 30.1,
    29.2, 28.3, 27.4, 26.5, 25.5, 24.6, 23.7, 22.9, 22.0, 21.1, 20.2, 19.4, 18.5, 17.7, 16.8,
    16.0, 15.2, 14.4, 13.7, 12.9, 12.2, 11.5, 10.8, 10.1, 9.5, 8.9, 8.4, 7.8, 7.3, 6.8,
    6.4, 6.0, 5.6, 5.2, 4.9, 4.6, 4.3, 4.1, 3.9, 3.7, 3.5, 3.4, 3.3, 3.1, 3.0,
    2.9, 2.8, 2.7, 2.5, 2.3, 2.0
  ]; // index 0 = age 10
  // RMD age (SECURE Act 2019, SECURE 2.0 Act 2022): born before July 1, 1949: 70 1/2;
  // July 1, 1949-1950: 72; 1951-1959: 73; 1960 or later: 75. RBD = April 1 of the next year.
  var ELECTION_FIRST_YEAR = 2024;
  // ------------------------------------------------------------------------------------------

  function singleLife(age) { return SINGLE_LIFE[Math.max(0, Math.min(120, age))]; }
  function uniform(age) { return UNIFORM[Math.max(10, Math.min(120, age)) - 10]; }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var d = { y: +m[1], m: +m[2], d: +m[3], iso: s };
    return d.m >= 1 && d.m <= 12 && d.d >= 1 && d.d <= 31 ? d : null;
  }
  function rmdStart(dob) {
    if (dob.y < 1949 || (dob.y === 1949 && dob.m < 7)) return { label: '70½', year: dob.y + 70 + (dob.m >= 7 ? 1 : 0) };
    var a = dob.y <= 1950 ? 72 : dob.y <= 1959 ? 73 : 75;
    return { label: String(a), year: dob.y + a };
  }
  function addHalfYear(dob, years) {
    var y = dob.y + years, m = dob.m + 6;
    if (m > 12) { m -= 12; y++; }
    return { y: y, m: m, d: Math.min(dob.d, new Date(Date.UTC(y, m, 0)).getUTCDate()) };
  }
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
                'October', 'November', 'December'];
  function longDate(x) { return MONTHS[x.m - 1] + ' ' + x.d + ', ' + x.y; }
  function iso(x) { return x.y + '-' + (x.m < 10 ? '0' : '') + x.m + '-' + (x.d < 10 ? '0' : '') + x.d; }

  // Returns { amount, divisor, table, first, deadline, note } or { unavailable: text }.
  function compute(opt, year, balance, owner, death, spouse) {
    var os = rmdStart(owner), ss = rmdStart(spouse), D = death.y;
    var rbd = (os.year + 1) + '-04-01', beforeRbd = death.iso < rbd;
    var age = year - spouse.y, ownerLE = beforeRbd ? 0 : singleLife(D - owner.y) - (year - D);
    var dec31 = 'December 31, ' + year;
    if (year === D) {
      if (beforeRbd) return { amount: 0, divisor: 0, table: 'None', first: null, deadline: 'None',
        note: 'The owner died before their required beginning date, so no RMD is due for ' + D + ', the year of death.' };
      var od = uniform(D - owner.y);
      return { amount: Math.min(balance, balance / od), divisor: od, table: 'Uniform Lifetime, owner’s age ' + (D - owner.y),
        first: D, deadline: dec31, yearOfDeath: true,
        note: 'In the year of death the owner’s own RMD applies, less anything the owner already withdrew that year.' +
          (spouse.y - owner.y > 10 ? ' Because you are more than 10 years younger, the owner’s RMD uses the IRS Joint and Last Survivor table (Table II), which gives a smaller amount than shown.' : '') };
    }
    var first, divisor = 0, table = '', deadline = dec31;
    if (opt === 'own') {
      first = Math.max(D + 1, ss.year);
      if (year >= first) { divisor = uniform(age); table = 'Uniform Lifetime, your age ' + age; }
      if (year === ss.year && year === first) deadline = 'April 1, ' + (year + 1) + ' (or ' + dec31 + ')';
    } else if (opt === 'ben' || opt === 'elect') {
      first = beforeRbd ? Math.max(D + 1, os.year) : D + 1;
      if (opt === 'elect' && first < ELECTION_FIRST_YEAR)
        return { unavailable: 'The spousal election is only available when the first beneficiary RMD year is 2024 or later; yours was ' + first + '.' };
      if (year >= first) {
        var own = opt === 'ben' ? singleLife(age) : uniform(age);
        var name = opt === 'ben' ? 'Single Life' : 'Uniform Lifetime';
        if (ownerLE > own) { divisor = ownerLE; table = 'Owner’s remaining life expectancy'; }
        else { divisor = own; table = name + ', your age ' + age; }
      }
    } else {
      if (!beforeRbd) return { unavailable: 'The 10-year option is only available when the owner died before their required beginning date (' + longDate(parseDate(rbd)) + ').' };
      first = D + 10;
      if (year > first) return { unavailable: 'Under the 10-year rule the whole account had to be withdrawn by December 31, ' + first + '.' };
      if (year < first) return { amount: 0, divisor: 0, table: 'None', first: first, deadline: 'Entire balance by December 31, ' + first,
        note: 'No withdrawal is required for ' + year + '. The whole account must be withdrawn by December 31, ' + first + '; spreading it over several years can keep you in a lower tax bracket.' };
      return { amount: balance, divisor: 0, table: 'None (full payout)', first: first, deadline: dec31,
        note: 'This is the final year: withdraw the entire remaining balance, including any growth since December 31, ' + (year - 1) + '.' };
    }
    if (year < first) return { amount: 0, divisor: 0, table: 'None', first: first, deadline: 'None',
      note: 'No RMD is due for ' + year + '. Under this option your first RMD is for ' + first + '.' };
    var amount = divisor > 1 ? balance / divisor : balance;
    return { amount: Math.min(balance, amount), divisor: divisor, table: table, first: first, deadline: deadline,
      note: (opt === 'own' ? 'As the owner you can name your own beneficiaries and keep contributing if you have earned income.'
        : 'You can switch to treating the IRA as your own in any later year.') };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var year = Math.round(num('scYear')), balance = num('scBalance'), opt = document.getElementById('scOption').value,
        owner = parseDate(document.getElementById('scOwnerDob').value),
        death = parseDate(document.getElementById('scDeath').value),
        spouse = parseDate(document.getElementById('scSpouseDob').value);
    var error = document.getElementById('scError'), msg = '';
    if (isNaN(year) || year < 2020 || year > 2100) msg = 'Enter a distribution year from 2020 to 2100.';
    else if (!owner || !death || !spouse) msg = 'Enter all three dates.';
    else if (death.y < 2020) msg = 'This calculator covers deaths in 2020 or later (SECURE Act rules).';
    else if (death.iso <= owner.iso) msg = 'The date of death must be after the owner’s date of birth.';
    else if (spouse.y < 1900 || spouse.y > death.y) msg = 'Enter a valid date of birth for the surviving spouse.';
    else if (year < death.y) msg = 'The distribution year must be the year of death (' + death.y + ') or later.';
    else if (year - spouse.y > 120) msg = 'The distribution year is past age 120 for the surviving spouse.';
    else if (isNaN(balance) || balance < 0) msg = 'Enter a non-negative account balance.';
    error.hidden = !msg;
    error.textContent = msg;
    if (!isNaN(year)) set('scBalYear', String(year - 1));
    if (msg) { ['scAmount', 'scDivisor', 'scAge', 'scDeadline'].forEach(function (id) { set(id, '–'); }); set('scNote', ''); set('scPenalty', ''); return; }

    var r = compute(opt, year, balance, owner, death, spouse);
    set('scAmountLabel', 'Required withdrawal for ' + year);
    set('scAge', String(year - spouse.y));
    if (r.unavailable) {
      set('scAmount', '–'); set('scDivisor', '–'); set('scDeadline', '–');
      set('scNote', r.unavailable); set('scPenalty', '');
      return;
    }
    set('scAmount', money(r.amount));
    set('scDivisor', r.divisor ? r.divisor.toFixed(1) + ' (' + r.table + ')' : r.table);
    set('scDeadline', r.deadline);
    set('scNote', r.note + (balance > 0 && r.amount > 0 ? ' That is ' + (r.amount / balance * 100).toFixed(2) + '% of the balance.' : ''));
    var half = addHalfYear(spouse, 59);
    var young = (year + '-01-01') < iso(half);
    set('scPenalty', !young ? 'You are 59½ or older for all of ' + year + ', so the 10% additional tax does not apply.'
      : opt === 'own' && !r.yearOfDeath ? 'You reach 59½ on ' + longDate(half) + '. Withdrawals from your own IRA before then are usually subject to the 10% additional tax.'
      : 'Withdrawals you take as a beneficiary are exempt from the 10% additional tax, even before 59½ (' + longDate(half) + ').');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('scForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
